import { sha256 } from './sha256.mjs';

function concatBytes(left, right) {
  const combined = new Uint8Array(left.length + right.length);
  combined.set(left);
  combined.set(right, left.length);
  return combined;
}

export function hmacSha256(key, message) {
  let normalizedKey = key;
  if (normalizedKey.length > 64) {
    normalizedKey = sha256(normalizedKey);
  }

  const block = new Uint8Array(64);
  block.set(normalizedKey);

  const outerPad = new Uint8Array(64);
  const innerPad = new Uint8Array(64);

  for (let index = 0; index < 64; index += 1) {
    outerPad[index] = block[index] ^ 0x5c;
    innerPad[index] = block[index] ^ 0x36;
  }

  const innerHash = sha256(concatBytes(innerPad, message));
  return sha256(concatBytes(outerPad, innerHash));
}

