function escapePythonString(value) {
  let escaped = '\'';

  for (const character of value) {
    const codePoint = character.codePointAt(0);

    if (character === '\\') {
      escaped += '\\\\';
      continue;
    }

    if (character === '\'') {
      escaped += '\\\'';
      continue;
    }

    if (character === '\n') {
      escaped += '\\n';
      continue;
    }

    if (character === '\r') {
      escaped += '\\r';
      continue;
    }

    if (character === '\t') {
      escaped += '\\t';
      continue;
    }

    if (character === '\b') {
      escaped += '\\x08';
      continue;
    }

    if (character === '\f') {
      escaped += '\\x0c';
      continue;
    }

    if (character === '\v') {
      escaped += '\\x0b';
      continue;
    }

    if (codePoint < 0x20 || (codePoint >= 0x7f && codePoint < 0xa0)) {
      escaped += `\\x${codePoint.toString(16).padStart(2, '0')}`;
      continue;
    }

    escaped += character;
  }

  return `${escaped}'`;
}

export function toPythonRepr(value) {
  if (value === null) {
    return 'None';
  }

  if (typeof value === 'string') {
    return escapePythonString(value);
  }

  if (typeof value === 'number') {
    if (Number.isNaN(value)) {
      return 'nan';
    }

    if (value === Infinity) {
      return 'inf';
    }

    if (value === -Infinity) {
      return '-inf';
    }

    return String(value);
  }

  if (typeof value === 'boolean') {
    return value ? 'True' : 'False';
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => toPythonRepr(item)).join(', ')}]`;
  }

  if (typeof value === 'object') {
    const entries = Object.entries(value)
      .map(([key, item]) => `${escapePythonString(key)}: ${toPythonRepr(item)}`);
    return `{${entries.join(', ')}}`;
  }

  throw new TypeError(`Unsupported value type: ${typeof value}`);
}

