import { base64urlToUtf8, bytesToBase64url, utf8ToBase64url } from './base64url.mjs';
import { hmacSha256 } from './hmacSha256.mjs';
import { encodeUtf8 } from './textCodec.mjs';

const DEFAULT_HEADER = Object.freeze({
  alg: 'HS256',
  typ: 'JWT',
});

function splitToken(token) {
  const parts = token.split('.');
  if (parts.length !== 3 || parts.some((part) => part.length === 0)) {
    throw new Error('Not enough segments');
  }
  return parts;
}

function encodeSegment(value) {
  return utf8ToBase64url(JSON.stringify(value));
}

function decodeSegment(segment) {
  return JSON.parse(base64urlToUtf8(segment));
}

export function encode(payload, secret) {
  const headerSegment = encodeSegment(DEFAULT_HEADER);
  const payloadSegment = encodeSegment(payload);
  const signingInput = `${headerSegment}.${payloadSegment}`;
  const signature = bytesToBase64url(
    hmacSha256(encodeUtf8(secret), encodeUtf8(signingInput)),
  );

  return `${signingInput}.${signature}`;
}

export function getUnverifiedClaims(token) {
  const [, payloadSegment] = splitToken(token);
  return decodeSegment(payloadSegment);
}

export function getUnverifiedHeader(token) {
  const [headerSegment] = splitToken(token);
  return decodeSegment(headerSegment);
}

