const OPTIONS = Object.freeze([
  { key: 'payload', long: '--payload', metavar: 'PAYLOAD', required: true },
  { key: 'secret', long: '--secret', metavar: 'SECRET', required: true },
]);

function isNegativeNumberToken(token) {
  return /^-(?:\d+(?:\.\d+)?|\.\d+)(?:[eE][+-]?\d+)?$/u.test(token);
}

function looksLikeOptional(token) {
  if (token === undefined) {
    return false;
  }

  if (token === '--') {
    return true;
  }

  if (token === '-' || !token.startsWith('-')) {
    return false;
  }

  if (token.startsWith('--')) {
    return true;
  }

  return !isNegativeNumberToken(token);
}

function formatUsage(programName) {
  const optionUsage = OPTIONS
    .map((option) => `${option.long} ${option.metavar}`)
    .join(' ');
  return `usage: ${programName} [-h] ${optionUsage}`;
}

function formatHelp(programName) {
  return `${formatUsage(programName)}\n\noptions:\n  -h, --help         show this help message and exit\n  --payload PAYLOAD\n  --secret SECRET\n`;
}

function buildError(programName, message) {
  return `${formatUsage(programName)}\n${programName}: error: ${message}\n`;
}

function resolveLongOption(name) {
  const exactMatch = OPTIONS.find((option) => option.long === name);
  if (exactMatch) {
    return { option: exactMatch, ambiguous: [] };
  }

  const matches = OPTIONS.filter((option) => option.long.startsWith(name));
  if (matches.length === 1) {
    return { option: matches[0], ambiguous: [] };
  }

  return { option: null, ambiguous: matches };
}

export class ParserExit extends Error {
  constructor(code, output, stream) {
    super(output);
    this.code = code;
    this.output = output;
    this.stream = stream;
  }
}

export function getProgramName(scriptPath) {
  const parts = String(scriptPath).split(/[\\/]/u);
  return parts[parts.length - 1] || String(scriptPath);
}

export function parseArgs(argv, programName) {
  const values = {};
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      throw new ParserExit(0, formatHelp(programName), 'stdout');
    }

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (token.startsWith('--')) {
      const equalsIndex = token.indexOf('=');
      const optionName = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
      const { option, ambiguous } = resolveLongOption(optionName);

      if (ambiguous.length > 1) {
        const names = ambiguous.map((item) => item.long).join(', ');
        throw new ParserExit(
          2,
          buildError(programName, `ambiguous option: ${optionName} could match ${names}`),
          'stderr',
        );
      }

      if (!option) {
        extras.push(token);
        continue;
      }

      if (equalsIndex !== -1) {
        values[option.key] = token.slice(equalsIndex + 1);
        continue;
      }

      const nextToken = argv[index + 1];
      if (nextToken === undefined || looksLikeOptional(nextToken)) {
        throw new ParserExit(
          2,
          buildError(programName, `argument ${option.long}: expected one argument`),
          'stderr',
        );
      }

      values[option.key] = nextToken;
      index += 1;
      continue;
    }

    extras.push(token);
  }

  const missing = OPTIONS
    .filter((option) => option.required && values[option.key] === undefined)
    .map((option) => option.long);

  if (missing.length > 0) {
    throw new ParserExit(
      2,
      buildError(programName, `the following arguments are required: ${missing.join(', ')}`),
      'stderr',
    );
  }

  if (extras.length > 0) {
    throw new ParserExit(
      2,
      buildError(programName, `unrecognized arguments: ${extras.join(' ')}`),
      'stderr',
    );
  }

  return values;
}

