import { decodeUtf8, encodeUtf8 } from './textCodec.mjs';

export function bytesToBase64url(bytes) {
  return Buffer.from(bytes)
    .toString('base64')
    .replace(/\+/gu, '-')
    .replace(/\//gu, '_')
    .replace(/=+$/u, '');
}

export function utf8ToBase64url(value) {
  return bytesToBase64url(encodeUtf8(value));
}

export function base64urlToBytes(value) {
  const normalized = value.replace(/-/gu, '+').replace(/_/gu, '/');
  const padLength = (4 - (normalized.length % 4)) % 4;
  const padded = normalized + '='.repeat(padLength);
  return Uint8Array.from(Buffer.from(padded, 'base64'));
}

export function base64urlToUtf8(value) {
  return decodeUtf8(base64urlToBytes(value));
}
